#if UNITY_EDITOR
using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
namespace StarterAssets.CQCEditorTools {
[InitializeOnLoad] public static class FixChapelDoors {
const string Request="Assets/Editor/CQC/FixChapelDoors-v2.request.txt";static double next;
static FixChapelDoors(){EditorApplication.update+=Poll;}
static void Poll(){if(EditorApplication.timeSinceStartup<next)return;next=EditorApplication.timeSinceStartup+2;if(!File.Exists(Request)||EditorApplication.isPlayingOrWillChangePlaymode||EditorApplication.isCompiling||EditorApplication.isUpdating)return;int group=Undo.GetCurrentGroup();try{Apply();AssetDatabase.DeleteAsset(Request);}catch(Exception e){Undo.RevertAllDownToGroup(group);File.WriteAllText("Logs/ChapelDoors-fix-error.txt",e.ToString());Debug.LogException(e);File.Move(Request,Request+".failed");}}
static Transform Anchor(Transform root,string name,Vector3 p,Vector3 facing){var t=root.Cast<Transform>().FirstOrDefault(c=>c.name==name||c.name.StartsWith(name+" ("));if(!t){t=new GameObject(name).transform;t.SetParent(root,false);Undo.RegisterCreatedObjectUndo(t.gameObject,"Add chapel entrance");}Undo.RecordObject(t,"Align chapel entrance");t.SetPositionAndRotation(p,Quaternion.LookRotation(facing));return t;}
static void Apply(){var active=SceneManager.GetActiveScene();var main=SceneManager.GetSceneByPath("Assets/Scenes/MyForest.unity");bool opened=!main.isLoaded;if(opened)main=EditorSceneManager.OpenScene("Assets/Scenes/MyForest.unity",OpenSceneMode.Additive);
try{SceneManager.SetActiveScene(main);var mountain=main.GetRootGameObjects().First(g=>g.name=="Castle Mountain");var church=mountain.transform.Find("Large Upper Castle Church");var portal=main.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<ChapelThroneDomain>(true)).Single();var player=portal.Player?portal.Player:GameObject.FindGameObjectWithTag("Player").transform;var cc=player.GetComponent<CharacterController>();var floor=mountain.transform.Find("Inner Castle Mountain/Flat Inner Castle Floor").GetComponent<MeshCollider>();Physics.SyncTransforms();
var transforms=mountain.GetComponentsInChildren<Transform>(true);var matrices=transforms.Select(t=>t.localToWorldMatrix).ToArray();var front=Vector3.ProjectOnPlane(-church.forward,Vector3.up).normalized;var center=church.GetComponentsInChildren<Renderer>().Aggregate(new Bounds(church.position,Vector3.zero),(b,r)=>{b.Encapsulate(r.bounds);return b;}).center;float y=floor.bounds.max.y;center.y=y;
var fronts=Locate(church,center,front,floor,cc);var backs=Locate(church,center+Vector3.Cross(Vector3.up,front)*3f,-front,floor,cc);
string backup="Assets/ForestExpansion/Backups/MyForest-before-chapel-both-doors-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".unity";if(!EditorSceneManager.SaveScene(main,backup,true))throw new IOException("Backup failed.");Undo.RecordObject(portal,"Fix front and back chapel entry");portal.Player=player;portal.ChapelDoor=Anchor(portal.transform,"Chapel Main Door Interaction",fronts[0],front);portal.OutsideReturn=Anchor(portal.transform,"Safe Courtyard Return",fronts[1],front);portal.BackDoor=Anchor(portal.transform,"Chapel Back Door Interaction",backs[0],-front);portal.BackOutsideReturn=Anchor(portal.transform,"Safe Back Courtyard Return",backs[1],-front);portal.InteractionRange=4.5f;AddRearDoor(portal,backs[0],-front);
for(int i=0;i<transforms.Length;i++)if(transforms[i].localToWorldMatrix!=matrices[i])throw new InvalidOperationException("Existing chapel model moved.");EditorSceneManager.MarkSceneDirty(main);if(!EditorSceneManager.SaveScene(main))throw new IOException("Save failed.");File.WriteAllText("Logs/ChapelDoors-fix.txt","Front interaction "+fronts[0]+" return "+fronts[1]+"\nBack interaction "+backs[0]+" return "+backs[1]+"\nBoth supported, capsule clear, one shared portal, existing castle transforms retained.\nBackup: "+backup);
}finally{if(active.IsValid()&&active.isLoaded)SceneManager.SetActiveScene(active);if(opened)EditorSceneManager.CloseScene(main,true);}}
static void AddRearDoor(ChapelThroneDomain portal,Vector3 interaction,Vector3 outward){const string folder="Assets/CityExpansion/ChapelThroneDomain/";var oak=AssetDatabase.LoadAssetAtPath<Material>(folder+"DomainDoorOak.mat");var stone=AssetDatabase.LoadAssetAtPath<Material>(folder+"ThroneStone.mat");var gold=AssetDatabase.LoadAssetAtPath<Material>(folder+"ThroneAgedGold.mat");var old=portal.transform.Find("Chapel Rear Domain Door");if(old)Undo.DestroyObjectImmediate(old.gameObject);var root=new GameObject("Chapel Rear Domain Door");Undo.RegisterCreatedObjectUndo(root,"Add rear chapel door");root.transform.SetParent(portal.transform,false);root.transform.SetPositionAndRotation(interaction-outward*.4f,Quaternion.LookRotation(outward));
Part(root.transform,"Closed Oak Double Door",new Vector3(0,1.8f,0),new Vector3(2.4f,3.6f,.22f),oak);foreach(int side in new[]{-1,1}){Part(root.transform,"Stone Jamb",new Vector3(side*1.35f,1.85f,0),new Vector3(.3f,3.9f,.42f),stone);Part(root.transform,"Door Handle",new Vector3(side*.17f,1.6f,.16f),new Vector3(.08f,.3f,.08f),gold);foreach(float height in new[]{.55f,2.85f})Part(root.transform,"Iron Strap",new Vector3(side*.62f,height,.14f),new Vector3(1.05f,.1f,.05f),gold);}Part(root.transform,"Stone Lintel",new Vector3(0,3.85f,0),new Vector3(3f,.3f,.5f),stone);Part(root.transform,"Threshold",new Vector3(0,-.01f,.15f),new Vector3(3f,.12f,.9f),stone);}
static void Part(Transform parent,string name,Vector3 p,Vector3 size,Material material){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=name;g.transform.SetParent(parent,false);g.transform.localPosition=p;g.transform.localScale=size;g.GetComponent<Renderer>().sharedMaterial=material;}
static Vector3[] Locate(Transform church,Vector3 center,Vector3 outward,MeshCollider floor,CharacterController cc){var origin=center+outward*100+Vector3.up*1.4f;float distance=200;Vector3 surface=Vector3.zero;bool found=false;foreach(var c in church.GetComponentsInChildren<Collider>())if(c.Raycast(new Ray(origin,-outward),out var hit,200)&&hit.distance<distance){distance=hit.distance;surface=hit.point;found=true;}if(!found)throw new InvalidOperationException("No chapel door surface on "+outward);
var door=surface+outward*.65f;door.y=center.y+.06f;foreach(float setback in new[]{2.5f,3f,3.5f,4f}){var point=door+outward*setback;if(!floor.Raycast(new Ray(point+Vector3.up*5,Vector3.down),out var support,10))continue;point.y=support.point.y+.06f;float radius=cc.radius;var overlaps=Physics.OverlapCapsule(point+Vector3.up*(radius+.13f),point+Vector3.up*(cc.height-radius),radius,~0,QueryTriggerInteraction.Ignore);if(overlaps.All(c=>c.transform.IsChildOf(cc.transform)))return new[]{door,point};}throw new InvalidOperationException("No supported unobstructed courtyard position at chapel door.");}
}}
#endif
